// --- #1: brick bounce ------------------------------------------------------

// Minimal canvas context: frame() only needs a drawing surface.
function mockCtx() {
  return {
    fillStyle: '',
    font: '',
    fillRect() {},
    fillText() {},
    beginPath() {},
    arc() {},
    fill() {},
  };
}

test('hitFace: ball under a brick hits its bottom face', () => {
  const ball = { x: 110, y: 112, r: 7, vx: 150, vy: -300 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(hitFace(ball, brick), 'bottom');
});

test('bounceBall: bottom face flips vy only and pushes the ball out', () => {
  const ball = { x: 110, y: 112, r: 7, vx: 150, vy: -300 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  bounceBall(ball, brick, 'bottom');
  assert.equal(ball.vy, 300, 'vertical velocity reflected');
  assert.equal(ball.vx, 150, 'horizontal velocity untouched');
  assert.equal(ball.y, brick.y + brick.h + ball.r, 'ball pushed below the brick');
  assert.equal(collides(ball, brick), false, 'no sticky re-collision');
});

test('bounceBall: ball above a brick hits its top face', () => {
  const ball = { x: 110, y: 88, r: 7, vx: 0, vy: 300 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(hitFace(ball, brick), 'top');
  bounceBall(ball, brick, 'top');
  assert.equal(ball.vy, -300);
  assert.equal(ball.y, brick.y - ball.r);
});

test('bounceBall: ball to the left of a brick hits its left face', () => {
  const ball = { x: 88, y: 100, r: 7, vx: 300, vy: 0 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(hitFace(ball, brick), 'left');
  bounceBall(ball, brick, 'left');
  assert.equal(ball.vx, -300);
  assert.equal(ball.x, brick.x - ball.r);
});

test('bounceBall: ball to the right of a brick hits its right face', () => {
  const ball = { x: 168, y: 100, r: 7, vx: -300, vy: 0 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(hitFace(ball, brick), 'right');
  bounceBall(ball, brick, 'right');
  assert.equal(ball.vx, 300);
  assert.equal(ball.x, brick.x + brick.w + ball.r);
});

test('bounceBall: corner overlap (equal penetration) is a diagonal hit', () => {
  const ball = { x: 100, y: 100, r: 7, vx: 200, vy: -300 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(hitFace(ball, brick), 'corner');
  bounceBall(ball, brick, 'corner');
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, 300);
  assert.equal(collides(ball, brick), false, 'pushed clear of the corner');
});

test('hitFace: a fast ball that jumps OVER a brick is still caught (sweep)', () => {
  const ball = { x: 120, y: 60, r: 7, vx: 0, vy: -700 };
  const brick = { x: 90, y: 90, w: 72, h: 20 };
  assert.equal(collides(ball, brick), false, 'discrete test misses the jump');
  assert.equal(hitFace(ball, brick, 120, 130), 'bottom', 'sweep catches it');
  bounceBall(ball, brick, 'bottom', 120, 130);
  assert.equal(ball.vy, 700, 'reflected downward');
  assert.ok(ball.y >= brick.y + brick.h, 'ball placed back below the brick');
});

test('frame: seam hit destroys both bricks and bounces exactly once', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 90, w: 72, h: 20, row: 0, alive: true, points: 100 },
    { x: 180, y: 90, w: 72, h: 20, row: 0, alive: true, points: 100 },
  ];
  state.ball = { x: 176, y: 100, r: 7, vx: 60, vy: -300, px: 176, py: 100 };
  frame(mockCtx(), state);
  assert.ok(state.bricks.every((b) => !b.alive), 'both seam bricks destroyed');
  assert.equal(state.ball.vx, 60, 'vx flipped exactly once (would be -60 if twice)');
  assert.equal(state.ball.vy, -300, 'a side hit leaves vy alone');
});

test('frame: a head-on hit reflects the ball off the brick', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 90, w: 72, h: 20, row: 0, alive: true, points: 100 },
  ];
  state.ball = { x: 136, y: 100, r: 7, vx: 0, vy: -300, px: 136, py: 130 };
  frame(mockCtx(), state);
  assert.equal(state.bricks[0].alive, false, 'brick destroyed');
  assert.equal(state.ball.vy, 300, 'ball bounces down');
  assert.equal(state.ball.vx, 0);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

