export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was BEFORE this step: frame() sweeps the segment
  // between the two positions to catch bricks the ball jumps over (#1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;

