    // straight through a column head-on AND straight through the side of a
    // row. Fix = a real per-face bounce (flip vy on a top/bottom hit, vx on a
    // side hit) plus pushing the ball back out of the brick.
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

edits.newText:
// Bricks: collision + bounce + score in one place (the entanglement with
// rendering is debt #2, kept deliberately). The sweep from the position
// recorded by step() catches tunnelling, and the bounce is applied at most
// ONCE per frame so overlapping a seam never double-flips the ball (#1).
const px = state.ball.px ?? state.ball.x;
const py = state.ball.py ?? state.ball.y;

// Detection pass (pure, on the ball BEFORE any bounce): every brick the
// ball touched this step, and which face it hit.
const hits = [];
for (const brick of state.bricks) {
  if (!brick.alive) continue;
  const face = hitFace(state.ball, brick, px, py);
  if (face) hits.push({ brick, face });
}

// Resolution pass: destroy every hit brick, then bounce the ball once.
for (const { brick } of hits) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}
if (hits.length > 0) {
  const { brick, face } = hits[0];
  bounceBall(state.ball, brick, face, px, py);
}

// Drawing (destroyed bricks simply disappear).
for (const brick of state.bricks) {
  if (!brick.alive) continue;
  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

